// src/emit-component.ts
//
// The sandboxed guest document for emit components.
//
// A tree component is workspace JavaScript. It must never run in the host tab
// (same origin as OPFS, keys and the sync stack), so the chat mounts it in an
// iframe with `sandbox="allow-scripts"` and no `allow-same-origin`. The guest
// document below is generated by the host, imports the component module from a
// `data:` URL, and talks back over postMessage only:
//
//   guest → host  { type: "bob-component-size", height }
//                 { type: "bob-component-ready" }
//                 { type: "bob-component-action", value }   // feed as a reply
//                 { type: "bob-component-error", message }
//   host → guest  { type: "bob-component-props", props }     // re-render
//
// The contract is vanilla by necessity (the guest is opaque-origin and cannot
// use the host's Solid runtime): default-export
//
//   render(root: HTMLElement, props: unknown, api: { action(v): void }): void
//
// v1 components are single-file: the guest imports the module once from a data
// URL, so sibling imports would not resolve. Inline helpers instead.

/** The host→guest theme keys the guest sets on its `:root`. */
export type ComponentTheme = Record<string, string>;

/** UTF-8 → base64 without blowing the argument stack on large sources. */
export function base64Utf8(text: string): string {
  const bytes = new TextEncoder().encode(text);
  let binary = "";
  const CHUNK = 0x8000;
  for (let i = 0; i < bytes.length; i += CHUNK) {
    binary += String.fromCharCode(...bytes.subarray(i, i + CHUNK));
  }
  return btoa(binary);
}

/** JSON that is safe to embed inside a `<script>` element. */
function scriptJson(value: unknown): string {
  const json = JSON.stringify(value === undefined ? null : value) ?? "null";
  return json.replace(/</g, "\\u003c");
}

/**
 * Build the guest HTML document for one component. Pure: the caller passes the
 * theme it wants the guest to inherit, so this is testable in Node.
 */
export function componentDoc(source: string, props: unknown, theme: ComponentTheme = {}): string {
  const sourceUrl = `data:text/javascript;base64,${base64Utf8(source)}`;
  return `<!doctype html>
<html>
<head>
<meta charset="utf-8">
<style>
  :root { color-scheme: dark; }
  html, body { margin: 0; padding: 0; background: transparent; }
  body {
    color: var(--bob-fg, #dbe4f5);
    font: var(--bob-font-size, 14px)/1.45 var(--bob-font, system-ui, sans-serif);
    overflow: hidden;
  }
  *, *::before, *::after { box-sizing: border-box; }
  #root { display: block; }
</style>
</head>
<body>
<div id="root"></div>
<script type="module">
const SOURCE_URL = ${scriptJson(sourceUrl)};
const INITIAL_PROPS = ${scriptJson(props)};
const THEME = ${scriptJson(theme)};
const root = document.getElementById("root");
for (const key of Object.keys(THEME)) {
  if (THEME[key]) document.documentElement.style.setProperty(key, THEME[key]);
}

let renderFn = null;
let props = INITIAL_PROPS;
let failed = false;

const api = Object.freeze({
  action(value) {
    if (typeof value === "string" && value) {
      parent.postMessage({ type: "bob-component-action", value }, "*");
    }
  },
  send(value) {
    if (typeof value === "string" && value) {
      parent.postMessage({ type: "bob-component-action", value }, "*");
    }
  },
  resize() { measure(); },
});

function measure() {
  // The iframe keeps the height the host last set, so scrollHeight would never
  // shrink. Measure the content boxes instead (the host clamps to >= 24px).
  const rootRect = root.getBoundingClientRect();
  const bodyRect = document.body ? document.body.getBoundingClientRect() : null;
  const height = Math.ceil(Math.max(rootRect.height, bodyRect ? bodyRect.height : 0, 1));
  parent.postMessage({ type: "bob-component-size", height }, "*");
}

function fail(err) {
  failed = true;
  const message = String(err && err.stack ? err.stack : err);
  parent.postMessage({ type: "bob-component-error", message }, "*");
  measure();
}

async function draw() {
  if (!renderFn || failed) return;
  try {
    root.textContent = "";
    await renderFn(root, props, api);
    parent.postMessage({ type: "bob-component-ready" }, "*");
  } catch (err) {
    fail(err);
  }
  measure();
}

window.addEventListener("message", (ev) => {
  const data = ev.data;
  if (!data || data.type !== "bob-component-props") return;
  props = data.props;
  void draw();
});

if (typeof ResizeObserver === "function") {
  new ResizeObserver(() => measure()).observe(root);
}

try {
  const mod = await import(SOURCE_URL);
  renderFn = mod.default ?? mod.render;
  if (typeof renderFn !== "function") {
    throw new Error("component must default-export render(root, props, api)");
  }
  await draw();
} catch (err) {
  fail(err);
}
</script>
</body>
</html>`;
}
